            eprintln!("error: invalid value '{}' for '--block-size <BLOCK_SIZE>': {}\n\nFor more information, try '--help'.", block_size_str, e);
            std::process::exit(2);
        }
    };

    let driver_str = matches.get_one::<String>("driver").unwrap().clone();
    let driver = match parse_driver(&driver_str) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--driver <DRIVER>': {}\n\nFor more information, try '--help'.", driver_str, e);
            std::process::exit(2);
        }
    };

    let reflink_str = matches.get_one::<String>("reflink").unwrap().clone();
    let reflink = match parse_reflink(&reflink_str) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--reflink <REFLINK>': {}\n\nFor more information, try '--help'.", reflink_str, e);
            std::process::exit(2);
        }
    };

    let backup_str = matches.get_one::<String>("backup").unwrap().clone();
    let backup = match parse_backup(&backup_str) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--backup <BACKUP>': {}\n\nFor more information, try '--help'.", backup_str, e);
            std::process::exit(2);
        }
    };

    let verbose = matches.get_count("verbose") as u8;
    let recursive = matches.get_flag("recursive");
    let dereference = matches.get_flag("dereference");
    let no_clobber = matches.get_flag("no-clobber");
    let force = matches.get_flag("force");
    let gitignore = matches.get_flag("gitignore");
    let glob_flag = matches.get_flag("glob");
    let no_perms = matches.get_flag("no-perms");
    let no_timestamps = matches.get_flag("no-timestamps");
    let no_target_directory = matches.get_flag("no-target-directory");
    let fsync = matches.get_flag("fsync");
    let target_directory_opt = matches.get_one::<String>("target-directory").map(|s| PathBuf::from(s));

    if no_clobber && force {
        eprintln!("Error: Invalid arguments: --force and --noclobber cannot be set at the same time.");
        std::process::exit(1);
    }

    if reflink == Reflink::Never {
        println!("{} --reflink=never is selected, however the Linux kernel may override this.", format_log("WARN"));
    }

    let paths: Vec<PathBuf> = if let Some(vals) = matches.get_many::<String>("paths") {
        vals.map(|s| PathBuf::from(s)).collect()
    } else {
        Vec::new()
    };

    if paths.is_empty() && target_directory_opt.is_none() {
        eprintln!("Error: Invalid arguments: Insufficient arguments");
        std::process::exit(1);
    }

    let (sources, dest) = if let Some(td) = target_directory_opt.clone() {
        if paths.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        (paths, td)
    } else {
        if paths.len() < 1 {
            eprintln!("Error: Invalid arguments: Insufficient arguments");
            std::process::exit(1);
        }
        if paths.len() == 1 {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        let dest = paths.last().unwrap().clone();
        let sources = paths[..paths.len()-1].to_vec();
        if sources.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        (sources, dest)
    };

    let mut expanded_sources: Vec<PathBuf> = Vec::new();
    if glob_flag {
        for src in &sources {
            let pattern = src.to_string_lossy().to_string();
            let mut _matched = false;
            for entry in glob::glob(&pattern).unwrap_or_else(|_| panic!("pattern error")) {
                if let Ok(p) = entry {
                    expanded_sources.push(p);
                    _matched = true;
                }
            }
        }
        if expanded_sources.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
    } else {
        expanded_sources = sources;
    }

    let dest_exists = dest.exists();
    let dest_is_dir = dest_exists && dest.is_dir();

    if expanded_sources.len() > 1 {
