            std::process::exit(1);
        }
    }

    // For each source, process
    // We'll use channel for jobs, and spawn workers early for concurrency

    let (job_tx, job_rx) = crossbeam_channel::unbounded::<Job>();
    let (err_tx, err_rx) = crossbeam_channel::unbounded::<String>();

    let failed = Arc::new(AtomicBool::new(false));
    let failed_clone_for_walk = failed.clone();

    // Spawn copy workers
    let mut worker_handles = Vec::new();
    for i in 0..num_workers {
        let rx = job_rx.clone();
        let failed_clone = failed.clone();
        let no_clobber_clone = no_clobber;
        let backup_clone = backup;
        let no_perms_clone = no_perms;
        let no_timestamps_clone = no_timestamps;
        let fsync_clone = fsync;
        let reflink_clone = reflink;
        let driver_clone = driver;
        let verbose_clone = verbose;
