                                    eprintln!("{} Received error: Error during copy: No such file or directory (os error 2)", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: No such file or directory (os error 2)");
                                } else if err_str.contains("Invalid argument") {
                                    eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
