                                    eprintln!("Error: Error during copy: {}", err_str);
                                }
                                failed_clone.store(true, Ordering::SeqCst);
                                let _ = err_tx_clone.send("error".to_string());
                                std::process::exit(1);
                            }
                        }
                    },
                    Job::Symlink { target, dst, src_for_log } => {
