                        if verbose_clone >= 2 {
                            println!("{} (3) libxcp::operations: Send copy operation {:?} to {:?}", format_log("DEBUG"), entry_path, dest_path);
                        }
                        let _ = job_tx_clone.send(Job::Copy { src: entry_path.to_path_buf(), dst: dest_path });
                    }
                }
            } else {
                // File source - already handled via jobs? Actually we need to send job for file source
                // We already computed target_base earlier, but need to push job
                // For file sources, we will handle here as well
                // Determine if symlink
                let src_path = src.clone();
                // Recompute target_base
                let dest_exists = dest_clone.exists();
                let dest_is_dir = dest_exists && dest_clone.is_dir();
                let target_base = if dest_exists && dest_is_dir && !no_target_directory_clone {
                    dest_clone.join(src_path.file_name().unwrap_or_default())
                } else {
                    dest_clone.clone()
                };
                // Check symlink
                if let Ok(meta) = fs::symlink_metadata(&src_path) {
                    if meta.file_type().is_symlink() {
                        if dereference_clone {
                            let _ = job_tx_clone.send(Job::Copy { src: src_path, dst: target_base });
                        } else {
                            if let Ok(link_target) = fs::read_link(&src_path) {
                                let _ = job_tx_clone.send(Job::Symlink { target: link_target, dst: target_base, src_for_log: src_path.clone() });
                            }
                        }
                    } else {
                        if verbose_clone >= 2 {
                            println!("{} (3) libxcp::operations: Got tree entry Ok(DirEntry({:?}))", format_log("DEBUG"), src_path);
                            println!("{} (3) libxcp::operations: Send copy operation {:?} to {:?}", format_log("DEBUG"), src_path, target_base);
                        }
                        let _ = job_tx_clone.send(Job::Copy { src: src_path, dst: target_base });
                    }
                }
            }
        }
        if verbose_clone >= 2 {
            println!("{} (3) libxcp::operations: Walk-worker finished: ThreadId(3)", format_log("DEBUG"));
        }
    });

    // Wait for walk to finish
    walk_handle.join().unwrap_or(());

    // Drop job tx so workers know no more jobs
    drop(job_tx);

    // Wait for workers
    for h in worker_handles {
        h.join().unwrap_or(());
    }

    // Check for errors
    if failed.load(Ordering::SeqCst) {
        std::process::exit(1);
    }

    if driver == Driver::ParBlock {
        if verbose >= 1 {
            println!("{} Queuing complete", format_log("INFO"));
            println!("{} Pool complete", format_log("INFO"));
        }
    }

    if verbose >= 1 {
        println!("{} Copy complete", format_log("INFO"));
    }
}
