    let expanded_sources_clone = expanded_sources.clone();
    let dest_clone = dest.clone();
    let verbose_clone = verbose;
    let recursive_clone = recursive;
    let dereference_clone = dereference;
    let no_target_directory_clone = no_target_directory;
    let gitignore_clone = gitignore;
    let failed_walk = failed.clone();
    let err_tx_walk = err_tx.clone();

    let walk_handle = std::thread::spawn(move || {
