                if let Ok(meta) = fs::symlink_metadata(&src_path) {
                    if meta.file_type().is_symlink() {
                        if dereference_clone {
                            let _ = job_tx_clone.send(Job::Copy { src: src_path, dst: target_base });
                        } else {
                            if let Ok(link_target) = fs::read_link(&src_path) {
                                let _ = job_tx_clone.send(Job::Symlink { target: link_target, dst: target_base, src_for_log: src_path.clone() });
