#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Backup { None, Off, Numbered, Auto }

fn parse_driver(s: &str) -> Result<Driver, String> {
    match s.to_ascii_lowercase().as_str() {
        "parfile" => Ok(Driver::ParFile),
        "parblock" => Ok(Driver::ParBlock),
        _ => Err(format!("Unknown driver: {}", s)),
    }
}
fn parse_reflink(s: &str) -> Result<Reflink, String> {
    match s.to_ascii_lowercase().as_str() {
        "auto" => Ok(Reflink::Auto),
        "always" => Ok(Reflink::Always),
        "never" => Ok(Reflink::Never),
        _ => Err(format!("Invalid arguments: Unexpected value for 'reflink': {}", s)),
    }
}
fn parse_backup(s: &str) -> Result<Backup, String> {
    match s.to_ascii_lowercase().as_str() {
        "none" => Ok(Backup::None),
        "off" => Ok(Backup::Off),
        "numbered" => Ok(Backup::Numbered),
        "auto" => Ok(Backup::Auto),
        _ => Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s)),
    }
}

fn parse_block_size(s: &str) -> Result<u64, String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        panic!("byte index 1 is out of bounds of ``");
    }
    let mut first_alpha_idx: Option<usize> = None;
    for (i, c) in trimmed.char_indices() {
        if c.is_ascii_alphabetic() {
            first_alpha_idx = Some(i);
            break;
        }
    }
    let (num_str, unit_str) = if let Some(idx) = first_alpha_idx {
        (trimmed[..idx].trim(), trimmed[idx..].trim())
    } else {
        (trimmed, "")
    };
    if num_str.is_empty() {
        return Err("could not interpret string as byte size".to_string());
    }
    if unit_str.contains(' ') || unit_str.contains('\t') {
        return Err("could not interpret string as byte size".to_string());
    }
    let mut dot_count = 0;
    let mut has_digit = false;
    for c in num_str.chars() {
        if c == '.' {
            dot_count+=1;
            if dot_count>1 { return Err("could not interpret string as byte size".to_string()); }
        } else if c.is_ascii_digit() {
            has_digit=true;
        } else {
            return Err("could not interpret string as byte size".to_string());
        }
    }
    if !has_digit {
        return Err("could not interpret string as byte size".to_string());
    }
    let num_val: f64 = match num_str.parse() {
        Ok(v) => v,
        Err(_) => return Err("could not interpret string as byte size".to_string()),
    };
    if unit_str.is_empty() {
        if num_str.contains('.') {
            let parts: Vec<&str> = num_str.split('.').collect();
            if parts.len()==2 {
                let frac = parts[1];
                if !frac.is_empty() && !frac.chars().all(|c| c=='0') {
                    return Err("could not interpret string as byte size".to_string());
                }
            }
        }
        return Ok(num_val as u64);
    }
    let unit_lower = unit_str.to_ascii_lowercase();
    let tokens = vec!["eib","pib","tib","gib","mib","kib","eb","pb","tb","gb","mb","kb","b","e","p","t","g","m","k"];
    let mut remaining = unit_lower.as_str();
    let mut multiplier: f64 = 1.0;
    let mut matched_any = false;
    while !remaining.is_empty() {
        let mut found=false;
        for token in &tokens {
            if remaining.starts_with(token) {
                let mult = match *token {
                    "b" => 1.0,
                    "k" | "kb" => 1000.0,
                    "m" | "mb" => 1000.0*1000.0,
                    "g" | "gb" => 1000.0*1000.0*1000.0,
                    "t" | "tb" => 1000.0*1000.0*1000.0*1000.0,
                    "p" | "pb" => 1000.0*1000.0*1000.0*1000.0*1000.0,
                    "e" | "eb" => 1000.0*1000.0*1000.0*1000.0*1000.0*1000.0,
                    "kib" => 1024.0,
                    "mib" => 1024.0*1024.0,
                    "gib" => 1024.0*1024.0*1024.0,
                    "tib" => 1024.0*1024.0*1024.0*1024.0,
                    "pib" => 1024.0*1024.0*1024.0*1024.0*1024.0,
                    "eib" => 1024.0*1024.0*1024.0*1024.0*1024.0*1024.0,
                    _ => 1.0,
                };
                multiplier*=mult;
                remaining=&remaining[token.len()..];
                matched_any=true;
                found=true;
                break;
            }
        }
        if !found {
            return Err("could not interpret string as byte size".to_string());
        }
    }
    if !matched_any {
        return Err("could not interpret string as byte size".to_string());
    }
    Ok((num_val*multiplier) as u64)
}

