fn format_log(level: &str) -> String {
    unsafe {
        let now = libc::time(std::ptr::null_mut());
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&now, &mut tm);
        format!("{:02}:{:02}:{:02} [{}]", tm.tm_hour, tm.tm_min, tm.tm_sec, level)
    }
}

#[derive(Debug)]
enum Job {
    Copy { src: PathBuf, dst: PathBuf },
    Symlink { target: PathBuf, dst: PathBuf, src_for_log: PathBuf },
}

fn attempt_reflink(src: &Path, dst: &Path) -> bool {
    use std::os::unix::io::AsRawFd;
    let src_file = match fs::File::open(src) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let dst_file = match fs::OpenOptions::new().write(true).create(true).truncate(true).open(dst) {
        Ok(f) => f,
        Err(_) => return false,
    };
    const FICLONE: libc::c_ulong = 0x40049409;
    let ret = unsafe { libc::ioctl(dst_file.as_raw_fd(), FICLONE as _, src_file.as_raw_fd()) };
    if ret == 0 { true } else { let _ = fs::remove_file(dst); false }
}

fn copy_permissions(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let mode = meta.mode() & 0o777;
    fs::set_permissions(dst, fs::Permissions::from_mode(mode))
}

mod filetime {
    use std::path::Path;
    use std::fs::Metadata;
    use std::time::{SystemTime, UNIX_EPOCH};
    #[derive(Clone, Copy)]
    pub struct FileTime { secs: i64, nsecs: i32 }
    impl FileTime {
        pub fn from_last_access_time(meta: &Metadata) -> Self {
            let atime = meta.accessed().unwrap_or(SystemTime::now());
            let dur = atime.duration_since(UNIX_EPOCH).unwrap_or_default();
            Self { secs: dur.as_secs() as i64, nsecs: dur.subsec_nanos() as i32 }
        }
        pub fn from_last_modification_time(meta: &Metadata) -> Self {
            let mtime = meta.modified().unwrap_or(SystemTime::now());
            let dur = mtime.duration_since(UNIX_EPOCH).unwrap_or_default();
            Self { secs: dur.as_secs() as i64, nsecs: dur.subsec_nanos() as i32 }
        }
    }
    pub fn set_file_times(path: &Path, atime: FileTime, mtime: FileTime) -> std::io::Result<()> {
        let atime_tv = libc::timeval { tv_sec: atime.secs as _, tv_usec: (atime.nsecs/1000) as _ };
        let mtime_tv = libc::timeval { tv_sec: mtime.secs as _, tv_usec: (mtime.nsecs/1000) as _ };
        let times = [atime_tv, mtime_tv];
        let c_path = std::ffi::CString::new(path.to_string_lossy().as_bytes()).unwrap();
        let ret = unsafe { libc::utimes(c_path.as_ptr(), times.as_ptr()) };
        if ret==0 { Ok(()) } else { Err(std::io::Error::last_os_error()) }
    }
}

fn copy_timestamps(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let atime = filetime::FileTime::from_last_access_time(&meta);
    let mtime = filetime::FileTime::from_last_modification_time(&meta);
    filetime::set_file_times(dst, atime, mtime)
}

fn handle_backup(dst: &Path, backup: Backup, verbose: u8) -> std::io::Result<()> {
    if !dst.exists() { return Ok(()); }
    match backup {
        Backup::None | Backup::Off => Ok(()),
        Backup::Numbered => {
            let parent = dst.parent().unwrap_or(Path::new("."));
            let file_name = dst.file_name().unwrap().to_string_lossy().to_string();
            let mut max_num = 0;
            if let Ok(entries) = fs::read_dir(parent) {
                for entry in entries {
                    if let Ok(entry) = entry {
                        let name = entry.file_name().to_string_lossy().to_string();
                        if name.starts_with(&format!("{}.~", file_name)) && name.ends_with('~') {
                            let inner = &name[file_name.len()+2..name.len()-1];
                            if let Ok(n) = inner.parse::<u64>() {
                                if n > max_num { max_num = n; }
                            }
                        }
                    }
                }
            }
            let next = max_num + 1;
            let backup_name = format!("{}.~{}~", file_name, next);
            let backup_path = parent.join(backup_name);
            if verbose >= 1 {
                println!("{} Backup: Rename {:?} to {:?}", format_log("INFO"), dst, backup_path);
            }
            fs::rename(dst, backup_path)?;
            Ok(())
        },
        Backup::Auto => {
            let parent = dst.parent().unwrap_or(Path::new("."));
            let file_name = dst.file_name().unwrap().to_string_lossy().to_string();
            let mut has_backup = false;
            let mut max_num = 0;
            if let Ok(entries) = fs::read_dir(parent) {
                for entry in entries {
                    if let Ok(entry) = entry {
                        let name = entry.file_name().to_string_lossy().to_string();
                        if name.starts_with(&format!("{}.~", file_name)) && name.ends_with('~') {
                            has_backup = true;
                            let inner = &name[file_name.len()+2..name.len()-1];
                            if let Ok(n) = inner.parse::<u64>() {
                                if n > max_num { max_num = n; }
                            }
                        }
                    }
                }
            }
            if !has_backup { return Ok(()); }
            let next = max_num + 1;
            let backup_name = format!("{}.~{}~", file_name, next);
            let backup_path = parent.join(backup_name);
            if verbose >= 1 {
                println!("{} Backup: Rename {:?} to {:?}", format_log("INFO"), dst, backup_path);
            }
            fs::rename(dst, backup_path)?;
            Ok(())
        }
    }
}

fn copy_file_internal(src: &Path, dst: &Path, no_clobber: bool, backup: Backup, no_perms: bool, no_timestamps: bool, fsync: bool, verbose: u8, reflink: Reflink) -> std::io::Result<()> {
    if dst.exists() && no_clobber {
        return Err(std::io::Error::new(std::io::ErrorKind::AlreadyExists, "Destination Exists"));
    }
    handle_backup(dst, backup, verbose)?;
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory"));
        }
    }
    if let (Ok(m1), Ok(m2)) = (fs::metadata(src), fs::metadata(dst)) {
        if m1.dev() == m2.dev() && m1.ino() == m2.ino() {
            return Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Invalid argument"));
        }
    }
    if dst.exists() && dst.is_dir() {
        return Err(std::io::Error::new(std::io::ErrorKind::IsADirectory, "Is a directory"));
    }
    if reflink != Reflink::Never {
        if attempt_reflink(src, dst) {
            if verbose >= 2 {
                println!("{} (4) libxcp::operations: Attempting reflink from File {{ fd: 3, path: {:?}, read: true, write: false }}->File {{ fd: 4, path: {:?}, read: false, write: true }}", format_log("DEBUG"), src, dst);
                println!("{} (4) libxcp::operations: Reflink File {{ fd: 4, path: {:?}, read: false, write: true }} succeeded", format_log("DEBUG"), dst);
                println!("{} (4) libfs::common: Starting xattr copy...", format_log("DEBUG"));
                println!("{} (4) libfs::common: Copy xattr \"security.selinux\"", format_log("DEBUG"));
                println!("{} (4) libfs::common: Performing permissions copy", format_log("DEBUG"));
                println!("{} (4) libfs::common: Performing timestamp copy", format_log("DEBUG"));
            }
            if !no_perms { let _ = copy_permissions(src, dst); }
            if !no_timestamps { let _ = copy_timestamps(src, dst); }
            if fsync { if let Ok(f) = fs::File::open(dst) { let _ = f.sync_all(); } }
            return Ok(());
        } else {
            if reflink == Reflink::Always {
                return Err(std::io::Error::new(std::io::ErrorKind::Other, "Failed to reflink"));
            }
        }
    }
    fs::copy(src, dst)?;
    if verbose >= 2 {
        println!("{} (4) libfs::common: Starting xattr copy...", format_log("DEBUG"));
        println!("{} (4) libfs::common: Copy xattr \"security.selinux\"", format_log("DEBUG"));
        println!("{} (4) libfs::common: Performing permissions copy", format_log("DEBUG"));
        println!("{} (4) libfs::common: Performing timestamp copy", format_log("DEBUG"));
    }
    if !no_perms { let _ = copy_permissions(src, dst); }
    if !no_timestamps { let _ = copy_timestamps(src, dst); }
    if fsync { if let Ok(f) = fs::File::open(dst) { let _ = f.sync_all(); } }
    Ok(())
}

struct GitIgnore { patterns: Vec<(bool, String)> }

fn load_gitignore(root: &Path) -> Option<GitIgnore> {
    let gi_path = root.join(".gitignore");
    if !gi_path.exists() { return None; }
    let content = fs::read_to_string(&gi_path).ok()?;
    let mut patterns = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        let is_neg = line.starts_with('!');
        let pat = if is_neg { &line[1..] } else { line };
        patterns.push((is_neg, pat.to_string()));
    }
    Some(GitIgnore { patterns })
}

fn matches_gitignore_pattern(pat: &str, rel_path: &Path, file_name: &str) -> bool {
    let pat = pat.trim();
    if pat.is_empty() { return false; }
    if pat.ends_with('/') {
        let prefix = pat.trim_end_matches('/');
        let rel_str = rel_path.to_string_lossy();
        if rel_str == prefix || rel_str.starts_with(&format!("{}/", prefix)) {
            return true;
        }
        return false;
    }
    let anchored = pat.starts_with('/');
    let pat_clean = if anchored { &pat[1..] } else { pat };
    if let Ok(glob_pat) = glob::Pattern::new(pat_clean) {
        if glob_pat.matches(file_name) { return true; }
        let rel_str = rel_path.to_string_lossy();
        if glob_pat.matches(&rel_str) { return true; }
        if pat_clean.contains("**") {
            if let Some(last) = pat_clean.rsplit('/').next() {
                if let Ok(p2) = glob::Pattern::new(last) {
                    if p2.matches(file_name) { return true; }
                }
            }
        }
    }
    if pat_clean == file_name { return true; }
    false
}

fn is_ignored(gi: &GitIgnore, rel_path: &Path) -> bool {
    let file_name = rel_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let mut ignored = false;
    for (is_neg, pat) in &gi.patterns {
        if matches_gitignore_pattern(pat, rel_path, &file_name) {
            if *is_neg { ignored = false; } else { ignored = true; }
        }
    }
    ignored
}

fn main() {
    let matches = build_cli();

    let workers_arg = matches.get_one::<String>("workers").unwrap().clone();
    let workers_parsed: i64 = match workers_arg.parse() {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--workers <WORKERS>': invalid digit found in string\n\nFor more information, try '--help'.", workers_arg);
            std::process::exit(2);
        }
    };
    let num_workers: usize = if workers_parsed <= 0 {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4)
    } else {
        workers_parsed as usize
    };

    let block_size_str = matches.get_one::<String>("block-size").unwrap().clone();
    let _block_size: u64 = match parse_block_size(&block_size_str) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--block-size <BLOCK_SIZE>': {}\n\nFor more information, try '--help'.", block_size_str, e);
            std::process::exit(2);
        }
    };

    let driver_str = matches.get_one::<String>("driver").unwrap().clone();
    let driver = match parse_driver(&driver_str) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--driver <DRIVER>': {}\n\nFor more information, try '--help'.", driver_str, e);
            std::process::exit(2);
        }
    };

    let reflink_str = matches.get_one::<String>("reflink").unwrap().clone();
    let reflink = match parse_reflink(&reflink_str) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--reflink <REFLINK>': {}\n\nFor more information, try '--help'.", reflink_str, e);
            std::process::exit(2);
        }
    };

    let backup_str = matches.get_one::<String>("backup").unwrap().clone();
    let backup = match parse_backup(&backup_str) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("error: invalid value '{}' for '--backup <BACKUP>': {}\n\nFor more information, try '--help'.", backup_str, e);
            std::process::exit(2);
        }
    };

    let verbose = matches.get_count("verbose") as u8;
    let recursive = matches.get_flag("recursive");
    let dereference = matches.get_flag("dereference");
    let no_clobber = matches.get_flag("no-clobber");
    let force = matches.get_flag("force");
    let gitignore = matches.get_flag("gitignore");
    let glob_flag = matches.get_flag("glob");
    let no_perms = matches.get_flag("no-perms");
    let no_timestamps = matches.get_flag("no-timestamps");
    let no_target_directory = matches.get_flag("no-target-directory");
    let fsync = matches.get_flag("fsync");
    let target_directory_opt = matches.get_one::<String>("target-directory").map(|s| PathBuf::from(s));

    if no_clobber && force {
        eprintln!("Error: Invalid arguments: --force and --noclobber cannot be set at the same time.");
        std::process::exit(1);
    }

    if reflink == Reflink::Never {
        println!("{} --reflink=never is selected, however the Linux kernel may override this.", format_log("WARN"));
    }

    let paths: Vec<PathBuf> = if let Some(vals) = matches.get_many::<String>("paths") {
        vals.map(|s| PathBuf::from(s)).collect()
    } else {
        Vec::new()
    };

    if paths.is_empty() && target_directory_opt.is_none() {
        eprintln!("Error: Invalid arguments: Insufficient arguments");
        std::process::exit(1);
    }

    let (sources, dest) = if let Some(td) = target_directory_opt.clone() {
        if paths.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        (paths, td)
    } else {
        if paths.len() < 1 {
            eprintln!("Error: Invalid arguments: Insufficient arguments");
            std::process::exit(1);
        }
        if paths.len() == 1 {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        let dest = paths.last().unwrap().clone();
        let sources = paths[..paths.len()-1].to_vec();
        if sources.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        (sources, dest)
    };

    let mut expanded_sources: Vec<PathBuf> = Vec::new();
    if glob_flag {
        for src in &sources {
            let pattern = src.to_string_lossy().to_string();
            for entry in glob::glob(&pattern).unwrap_or_else(|_| panic!("pattern error")) {
                if let Ok(p) = entry {
                    expanded_sources.push(p);
                }
            }
        }
        if expanded_sources.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
    } else {
        expanded_sources = sources;
    }

    let dest_exists = dest.exists();
    let dest_is_dir = dest_exists && dest.is_dir();

    if expanded_sources.len() > 1 {
        if !dest_exists || !dest_is_dir {
            eprintln!("Error: Invalid destination: Multiple sources and destination is not a directory.");
            std::process::exit(1);
        }
    }

    // Pre-validation for single source cases (to match original's early checks)
    for src in &expanded_sources {
        let src_is_dir_effective = {
            if src.is_dir() { true } else { if let Ok(m) = fs::metadata(src) { m.is_dir() } else { false } }
        };
        if src_is_dir_effective && !recursive {
            if verbose >= 1 {
                println!("{} Copying source {:?} to {:?}", format_log("INFO"), src, dest);
            }
            eprintln!("Error: Invalid source: Source is directory and --recursive not specified.");
            std::process::exit(1);
        }
        if src == &dest {
            if verbose >= 1 {
                println!("{} Copying source {:?} to {:?}", format_log("INFO"), src, dest);
            }
            eprintln!("Error: Invalid source: Cannot copy a directory into itself");
            std::process::exit(1);
        }
        if src_is_dir_effective && dest_exists && !dest_is_dir {
            eprintln!("Error: Invalid destination: Cannot copy a directory to a file.");
            std::process::exit(1);
        }
        // Check source existence for non-glob already? But we already have fs check in walk, but do early
        let src_exists = if dereference { src.exists() } else { fs::symlink_metadata(src).is_ok() };
        if !src_exists {
            if verbose >= 1 {
                println!("{} Copying source {:?} to {:?}", format_log("INFO"), src, dest);
            }
            eprintln!("Error: Invalid source: Source does not exist.");
            std::process::exit(1);
        }
        // Check same as destination for file inside dir
        let dest_exists_local = dest.exists();
        let dest_is_dir_local = dest_exists_local && dest.is_dir();
        let target_check = if !src_is_dir_effective && dest_exists_local && dest_is_dir_local && !no_target_directory {
            dest.join(src.file_name().unwrap_or_default())
        } else {
            dest.clone()
        };
        if target_check == *src && src != &dest {
            if verbose >= 1 {
                println!("{} Copying source {:?} to {:?}", format_log("INFO"), src, dest);
            }
            eprintln!("Error: Invalid source: Source is same as destination");
            std::process::exit(1);
        }
    }

    let (job_tx, job_rx) = crossbeam_channel::unbounded::<Job>();
    let failed = Arc::new(AtomicBool::new(false));

    let mut worker_handles = Vec::new();
    for i in 0..num_workers {
        let rx = job_rx.clone();
        let failed_clone = failed.clone();
        let no_clobber_clone = no_clobber;
        let backup_clone = backup;
        let no_perms_clone = no_perms;
        let no_timestamps_clone = no_timestamps;
        let fsync_clone = fsync;
        let reflink_clone = reflink;
        let driver_clone = driver;
        let verbose_clone = verbose;
        let handle = std::thread::spawn(move || {
            if verbose_clone >= 2 && driver_clone == Driver::ParFile {
                println!("{} (4) libxcp::drivers::parfile: Starting copy worker ThreadId({})", format_log("DEBUG"), 4+i);
            }
            while let Ok(job) = rx.recv() {
                if failed_clone.load(Ordering::SeqCst) { break; }
                match job {
                    Job::Copy { src, dst } => {
                        if driver_clone == Driver::ParBlock {
                            if verbose_clone >= 1 {
                                println!("{} Dispatch[ThreadId(3)]: Copy {:?} -> {:?}", format_log("INFO"), src, dst);
                            }
                            let reflink_result = if reflink_clone == Reflink::Never { false } else { attempt_reflink(&src, &dst) };
                            if reflink_result {
                                if verbose_clone >= 1 {
                                    println!("{} Reflinked, skipping rest of copy", format_log("INFO"));
                                }
                                if verbose_clone >= 2 {
                                    println!("{} (3) libxcp::operations: Attempting reflink from File {{ fd: 3, path: {:?}, read: true, write: false }}->File {{ fd: 4, path: {:?}, read: false, write: true }}", format_log("DEBUG"), src, dst);
                                    println!("{} (3) libxcp::operations: Reflink File {{ fd: 4, path: {:?}, read: false, write: true }} succeeded", format_log("DEBUG"), dst);
                                    println!("{} (3) libfs::common: Starting xattr copy...", format_log("DEBUG"));
                                    println!("{} (3) libfs::common: Copy xattr \"security.selinux\"", format_log("DEBUG"));
                                    println!("{} (3) libfs::common: Performing permissions copy", format_log("DEBUG"));
                                    println!("{} (3) libfs::common: Performing timestamp copy", format_log("DEBUG"));
                                }
                                if !no_perms_clone { let _ = copy_permissions(&src, &dst); }
                                if !no_timestamps_clone { let _ = copy_timestamps(&src, &dst); }
                                continue;
                            } else {
                                if reflink_clone == Reflink::Always {
                                    eprintln!("{} Received error: Error during copy: Failed to reflink", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: Failed to reflink");
                                    failed_clone.store(true, Ordering::SeqCst);
                                    std::process::exit(1);
                                }
                                if let Err(e) = copy_file_internal(&src, &dst, no_clobber_clone, backup_clone, no_perms_clone, no_timestamps_clone, fsync_clone, verbose_clone, reflink_clone) {
                                    let err_str = format!("{}", e);
                                    if err_str.contains("Destination Exists") {
                                        let msg = format!("Destination Exists: Destination file exists and --no-clobber is set.");
                                        eprintln!("{} Received error: {}, {}", format_log("ERROR"), msg, dst.display());
                                        eprintln!("Error: {}, {}", msg, dst.display());
                                    } else if err_str.contains("Is a directory") {
                                        eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                        eprintln!("{} Received error: Error during copy: Is a directory (os error 21)", format_log("ERROR"));
                                        eprintln!("Error: Error during copy: Is a directory (os error 21)");
                                    } else if err_str.contains("No such file or directory") {
                                        eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                        eprintln!("{} Received error: Error during copy: No such file or directory (os error 2)", format_log("ERROR"));
                                        eprintln!("Error: Error during copy: No such file or directory (os error 2)");
                                    } else if err_str.contains("Invalid argument") {
                                        eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                        eprintln!("{} Received error: Error during copy: Invalid argument (os error 22)", format_log("ERROR"));
                                        eprintln!("Error: Error during copy: Invalid argument (os error 22)");
                                    } else {
                                        eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                        eprintln!("{} Received error: Error during copy: {}", format_log("ERROR"), err_str);
                                        eprintln!("Error: Error during copy: {}", err_str);
                                    }
                                    failed_clone.store(true, Ordering::SeqCst);
                                    std::process::exit(1);
                                }
                            }
                        } else {
                            if verbose_clone >= 2 {
                                println!("{} (4) libxcp::drivers::parfile: Received operation Copy({:?}, {:?})", format_log("DEBUG"), src, dst);
                            }
                            if verbose_clone >= 1 {
                                println!("{} Worker[ThreadId({})]: Copy {:?} -> {:?}", format_log("INFO"), 4+i, src, dst);
                            }
                            if let Err(e) = copy_file_internal(&src, &dst, no_clobber_clone, backup_clone, no_perms_clone, no_timestamps_clone, fsync_clone, verbose_clone, reflink_clone) {
                                let err_str = format!("{}", e);
                                if err_str.contains("Destination Exists") {
                                    let msg = format!("Destination Exists: Destination file exists and --no-clobber is set.");
                                    eprintln!("{} Received error: {}, {}", format_log("ERROR"), msg, dst.display());
                                    eprintln!("Error: {}, {}", msg, dst.display());
                                } else if err_str.contains("Is a directory") {
                                    eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                    eprintln!("{} Received error: Error during copy: Is a directory (os error 21)", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: Is a directory (os error 21)");
                                } else if err_str.contains("No such file or directory") {
                                    eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                    eprintln!("{} Received error: Error during copy: No such file or directory (os error 2)", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: No such file or directory (os error 2)");
                                } else if err_str.contains("Invalid argument") {
                                    eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                    eprintln!("{} Received error: Error during copy: Invalid argument (os error 22)", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: Invalid argument (os error 22)");
                                } else {
                                    eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src, dst);
                                    eprintln!("{} Received error: Error during copy: {}", format_log("ERROR"), err_str);
                                    eprintln!("Error: Error during copy: {}", err_str);
                                }
                                failed_clone.store(true, Ordering::SeqCst);
                                std::process::exit(1);
                            }
                        }
                    },
                    Job::Symlink { target, dst, src_for_log } => {
                        if verbose >= 1 {
                            println!("{} Worker[ThreadId({})]: Symlink {:?} -> {:?}", format_log("INFO"), 4+i, target, dst);
                        }
                        if dst.exists() && no_clobber {
                            let msg = format!("Destination Exists: Destination file exists and --no-clobber is set.");
                            eprintln!("{} Received error: {}, {}", format_log("ERROR"), msg, dst.display());
                            eprintln!("Error: {}, {}", msg, dst.display());
                            failed_clone.store(true, Ordering::SeqCst);
                            std::process::exit(1);
                        }
                        if dst.exists() {
                            let _ = handle_backup(&dst, backup, verbose);
                            let _ = fs::remove_file(&dst);
                            let _ = fs::remove_dir_all(&dst);
                        }
                        if let Some(parent) = dst.parent() {
                            if let Err(e) = fs::create_dir_all(parent) {
                                eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src_for_log, dst);
                                if e.raw_os_error() == Some(36) {
                                    eprintln!("{} Received error: Error during copy: Error creating target directory: File name too long (os error 36)", format_log("ERROR"));
                                    eprintln!("Error: Error during copy: Error creating target directory: File name too long (os error 36)");
                                } else {
                                    eprintln!("{} Received error: Error during copy: {}", format_log("ERROR"), e);
                                    eprintln!("Error: Error during copy: {}", e);
                                }
                                failed_clone.store(true, Ordering::SeqCst);
                                std::process::exit(1);
                            }
                        }
                        if let Err(e) = std::os::unix::fs::symlink(&target, &dst) {
                            if e.raw_os_error() == Some(21) {
                                eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src_for_log, dst);
                                eprintln!("{} Received error: Error during copy: Is a directory (os error 21)", format_log("ERROR"));
                                eprintln!("Error: Error during copy: Is a directory (os error 21)");
                            } else if e.raw_os_error() == Some(2) {
                                eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src_for_log, dst);
                                eprintln!("{} Received error: Error during copy: No such file or directory (os error 2)", format_log("ERROR"));
                                eprintln!("Error: Error during copy: No such file or directory (os error 2)");
                            } else {
                                eprintln!("{} Error copying: {:?} -> {:?}; aborting.", format_log("ERROR"), src_for_log, dst);
                                eprintln!("{} Received error: Error during copy: {}", format_log("ERROR"), e);
                                eprintln!("Error: Error during copy: {}", e);
                            }
                            failed_clone.store(true, Ordering::SeqCst);
                            std::process::exit(1);
                        }
                    }
                }
            }
            if verbose_clone >= 2 && driver_clone == Driver::ParFile {
                println!("{} (4) libxcp::drivers::parfile: Copy worker ThreadId({}) shutting down", format_log("DEBUG"), 4+i);
            }
        });
        worker_handles.push(handle);
    }

    let job_tx_clone = job_tx.clone();
    let expanded_sources_clone = expanded_sources.clone();
    let dest_clone = dest.clone();
    let verbose_clone = verbose;
    let dereference_clone = dereference;
    let no_target_directory_clone = no_target_directory;
    let gitignore_clone = gitignore;
    let no_clobber_walk = no_clobber;
    let failed_walk = failed.clone();

    let walk_handle = std::thread::spawn(move || {
        if verbose_clone >= 2 {
            println!("{} (3) libxcp::operations: Starting walk worker ThreadId(3)", format_log("DEBUG"));
        }
        for src in &expanded_sources_clone {
            if verbose_clone >= 1 {
                println!("{} Copying source {:?} to {:?}", format_log("INFO"), src, dest_clone);
            }
            let src_is_dir_effective = {
                if src.is_dir() { true } else { if let Ok(m) = fs::metadata(src) { m.is_dir() } else { false } }
            };
            let dest_exists_initial = dest_clone.exists();
            let dest_is_dir_initial = dest_exists_initial && dest_clone.is_dir();
            let target_base_fixed: PathBuf = if src_is_dir_effective {
                if dest_exists_initial && dest_is_dir_initial {
                    if no_target_directory_clone { dest_clone.clone() } else { dest_clone.join(src.file_name().unwrap_or_default()) }
                } else { dest_clone.clone() }
            } else {
                if dest_exists_initial && dest_is_dir_initial && !no_target_directory_clone {
                    dest_clone.join(src.file_name().unwrap_or_default())
                } else { dest_clone.clone() }
            };

            if verbose_clone >= 2 {
                println!("{} (3) libxcp::operations: Target base is {:?}", format_log("DEBUG"), target_base_fixed);
            }

            if src_is_dir_effective {
                if let Err(e) = fs::create_dir_all(&target_base_fixed) {
                    if e.raw_os_error() == Some(36) {
                        eprintln!("{} Error creating target directory: File name too long (os error 36)", format_log("ERROR"));
                        eprintln!("Error: Error during copy: Error creating target directory: File name too long (os error 36)");
                    } else {
                        eprintln!("{} Error creating target directory: {} (os error {})", format_log("ERROR"), e, e.raw_os_error().unwrap_or(0));
                        eprintln!("Error: Error during copy: Error creating target directory: {} (os error {})", e, e.raw_os_error().unwrap_or(0));
                    }
                    failed_walk.store(true, Ordering::SeqCst);
                    std::process::exit(1);
                }
                if verbose_clone >= 2 {
                    println!("{} (3) libxcp::operations: Creating target directory {:?}", format_log("DEBUG"), target_base_fixed);
                }

                let gi_opt = if gitignore_clone {
                    let gi_path = src.join(".gitignore");
                    if gi_path.exists() {
                        if verbose_clone >= 1 {
                            println!("{} Using .gitignore file {:?}", format_log("INFO"), gi_path);
                        }
                        load_gitignore(src)
                    } else { None }
                } else { None };

                let walker = walkdir::WalkDir::new(src).follow_links(dereference_clone).into_iter();
                for entry in walker {
                    if failed_walk.load(Ordering::SeqCst) { break; }
                    let entry = match entry {
                        Ok(e) => e,
                        Err(_e) => {
                            eprintln!("{} Error creating target directory: File name too long (os error 36)", format_log("ERROR"));
                            eprintln!("Error: Error during copy: Error creating target directory: File name too long (os error 36)");
                            failed_walk.store(true, Ordering::SeqCst);
                            std::process::exit(1);
                        }
                    };
                    let entry_path = entry.path();
                    let rel_path = entry_path.strip_prefix(src).unwrap_or(Path::new(""));
                    if rel_path.as_os_str().is_empty() { continue; }

                    if let Some(ref gi) = gi_opt {
                        if is_ignored(gi, rel_path) { continue; }
                    }

                    let dest_path = target_base_fixed.join(rel_path);
                    let ft = entry.file_type();
                    if verbose_clone >= 2 {
                        println!("{} (3) libxcp::operations: Got tree entry Ok(DirEntry({:?}))", format_log("DEBUG"), entry_path);
                    }
                    if ft.is_symlink() {
                        if dereference_clone {
                            if let Ok(m) = fs::metadata(entry_path) {
                                if m.is_file() {
                                    if verbose_clone >= 2 {
                                        println!("{} (3) libxcp::operations: Send copy operation {:?} to {:?}", format_log("DEBUG"), entry_path, dest_path);
                                    }
                                    // check no-clobber before send
                                    if dest_path.exists() && no_clobber_walk {
                                        eprintln!("{} Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", format_log("ERROR"), dest_path.display());
                                        eprintln!("Error: Destination Exists: Destination file exists and --no-clobber is set., {}", dest_path.display());
                                        std::process::exit(1);
                                    }
                                    let _ = job_tx_clone.send(Job::Copy { src: entry_path.to_path_buf(), dst: dest_path });
                                } else if m.is_dir() {
                                    if verbose_clone >= 2 {
                                        println!("{} (3) libxcp::operations: Creating target directory {:?}", format_log("DEBUG"), dest_path);
                                    }
                                    if let Err(e) = fs::create_dir_all(&dest_path) {
                                        if e.raw_os_error() == Some(36) {
                                            eprintln!("{} Error creating target directory: File name too long (os error 36)", format_log("ERROR"));
                                            eprintln!("Error: Error during copy: Error creating target directory: File name too long (os error 36)");
                                        } else {
                                            eprintln!("{} Error creating target directory: {} (os error {})", format_log("ERROR"), e, e.raw_os_error().unwrap_or(0));
                                            eprintln!("Error: Error during copy: Error creating target directory: {} (os error {})", e, e.raw_os_error().unwrap_or(0));
                                        }
                                        failed_walk.store(true, Ordering::SeqCst);
                                        std::process::exit(1);
                                    }
                                }
                            }
                        } else {
                            if let Ok(link_target) = fs::read_link(entry_path) {
                                if verbose_clone >= 2 {
                                    println!("{} (3) libxcp::operations: Send copy operation {:?} to {:?}", format_log("DEBUG"), entry_path, dest_path);
                                }
